#version 300 es
precision highp float;
precision highp int;
uniform vec4 k[40];
#define texel k[0]
#define prm k[1]
#define saturate(x) clamp(x,0.0,1.0)
in vec2 vUV;in vec2 vUV2;in vec4 vColor;out vec4 outColor;uniform vec4 flip;
uniform sampler2D s0;
vec4 sample_spr(vec2 p){return texture(s0,vec2(p.x,mix(p.y,1.0-p.y,flip[0])));}





vec4 shade(vec2 uv , vec4 col )
{
  vec2 r = texel.xy * prm.x;
  vec2 h = r * 0.5;
  vec4 s = sample_spr( uv) * 0.16;
  s += (sample_spr( uv + vec2(h.x, 0.0)) + sample_spr( uv - vec2(h.x, 0.0)) +
        sample_spr( uv + vec2(0.0, h.y)) + sample_spr( uv - vec2(0.0, h.y))) * 0.11;
  s += (sample_spr( uv + r * vec2(0.71, 0.71)) + sample_spr( uv + r * vec2(-0.71, 0.71)) +
        sample_spr( uv + r * vec2(0.71, -0.71)) + sample_spr( uv + r * vec2(-0.71, -0.71)) +
        sample_spr( uv + vec2(r.x, 0.0)) + sample_spr( uv - vec2(r.x, 0.0)) +
        sample_spr( uv + vec2(0.0, r.y)) + sample_spr( uv - vec2(0.0, r.y))) * 0.05;
  return s * col;
}

void main(){outColor=shade(vUV,vColor);}

