#define saturate(x) clamp(x,0.0,1.0)
layout(location=0) in vec4 aPos;layout(location=1) in vec4 aColor;layout(location=2) in vec2 aUV;layout(location=3) in vec2 aUV2;out vec2 vUV;out vec2 vUV2;out vec4 vColor;





struct VI
{
  vec4 p ;
  vec4 c ;
  vec2 t0 ;
  vec2 t1 ;
};
struct VO
{
  vec4 p ;
  vec4 c ;
  vec2 t0 ;
  vec2 t1 ;
};
VO shade(VI i){
  VO o;
  o.p = vec4(i.p.x * k.x - 1.0, i.p.y * k.y + 1.0, i.p.z, 1.0);
  o.c = i.c;
  o.t0 = i.t0;
  o.t1 = i.t1;
  return o;
}

void main(){VI inputValue;inputValue.p=aPos;inputValue.c=aColor.bgra;inputValue.t0=aUV;inputValue.t1=aUV2;VO result=shade(inputValue);gl_Position=result.p+vec4(vk[0].xy*0.5,0,0);vUV=result.t0;vUV2=result.t1;vColor=result.c;}

murk:
#version 300 es
precision highp float;
precision highp int;
uniform vec4 k[40];
#define k0 k[0]
#define mc k[1]
#define mf k[2]
#define saturate(x) clamp(x,0.0,1.0)
in vec2 vUV;in vec2 vUV2;in vec4 vColor;out vec4 outColor;uniform vec4 flip;
uniform sampler2D s0;
vec4 sample_tile(vec2 p){return texture(s0,vec2(p.x,mix(p.y,1.0-p.y,flip[0])));}
uniform sampler2D s1;
vec4 sample_dev(vec2 p){return texture(s1,vec2(p.x,mix(p.y,1.0-p.y,flip[1])));}










vec4 shade(vec2 uv , vec2 uv2 , vec4 col )
{
  vec3 t = sample_tile( uv).rgb;
  float d = (sample_dev( uv2).r * 255.0 - 128.0) / 127.0;

  vec3 m = saturate((1.0 - t) + d * (1.0 - mc.rgb));

  float f = saturate((uv2.y - mf.x) * mf.y);
  return vec4(1.0 - m * mc.w * f * col.a, 1.0);
}

void main(){outColor=shade(vUV,vUV2,vColor);}

