particles_vs:
#version 300 es
precision highp float;
precision highp int;
uniform vec4 vk[12];
#define p0 vk[0]
#define p1 vk[1]
#define area vk[4]
#define vel vk[5]
#define mot vk[6]
#define sz vk[7]
#define reg vk[8]
#define ext vk[9]
#define tint vk[10]
#define saturate(x) clamp(x,0.0,1.0)
layout(location=0) in vec4 aPos;layout(location=1) in vec4 aB;layout(location=2) in vec4 aC;out vec2 vUV;out vec2 vUV2;out vec4 vColor;











struct VOut { vec4 pos ; vec2 uv ; vec4 col ; };
float hash(float n) { return fract(sin(n) * 43758.5453); }
VOut shade(vec4 a , vec4 b , vec4 c ){
  VOut o;
  float t = ext.w;
  float hasLife = step(0.0001, vel.w);
  float life = max(vel.w, 0.0001);

  float ph = t / life + b.x;
  float cyc = floor(ph);
  float k = mix(0.5, ph - cyc, hasLife);
  float rx = mix(a.z, hash(cyc * 12.9898 + a.z * 78.233), hasLife);
  float ry = mix(a.w, hash(cyc * 39.346 + a.w * 11.135), hasLife);
  float tt = mix(t, k * life, hasLife);
  float fade = mix(1.0, sin(k * 3.14159), hasLife);
  vec2 v = vel.xy * (1.0 + (b.y - 0.5) * 2.0 * vel.z);
  vec2 w;
  w.x = rx * area.x + v.x * tt + sin(t * mot.y * 6.2832 + b.z * 6.2832) * mot.x - area.z;
  w.y = ry * area.y + v.y * tt - area.w;

  w.x = fract(w.x / area.x) * area.x - ext.x;
  float onLine = step(0.0, ext.y);
  w.y = mix(fract(w.y / area.y) * area.y - ext.x, ext.y - area.w, onLine);
  float size = mix(sz.x, sz.y, b.w) * mix(1.0, ext.z, k);
  vec2 q = (a.xy - 0.5) * c.zw * size;

  vec2 d = normalize(v + vec2(0.0001, 0.0001));
  vec2 qs = vec2(q.x * d.y + q.y * d.x * mot.w, -q.x * d.x + q.y * d.y * mot.w);
  float ang = mot.z * (b.z - 0.5) * 2.0 * t + b.x * 6.2832;
  float cs = cos(ang);
  float sn = sin(ang);
  vec2 qr = vec2(q.x * cs - q.y * sn, q.x * sn + q.y * cs);
  vec2 pos = w + mix(qr, qs, step(0.0001, mot.w));

  float wx = w.x + area.z;
  float inReg = saturate((wx - reg.x) / reg.z) * saturate((reg.y - wx) / reg.z);
  float rf = mix(1.0, inReg, step(reg.x + 0.5, reg.y));
  float al = tint.a * reg.w * fade * rf;
  vec2 s = p0.zw + pos * p1.x - 0.5;
  o.pos = vec4(s.x * p0.x - 1.0, s.y * p0.y + 1.0, 0.0, 1.0);
  o.uv = c.xy;
  o.col = vec4(tint.rgb * al, al);
  return o;
}

void main(){VOut result=shade(aPos,aB,aC);gl_Position=result.pos+vec4(vk[0].xy*0.5,0,0);vUV=result.uv;vUV2=vec2(0);vColor=result.col;}

