#version 300 es
precision highp float;
precision highp int;
uniform vec4 k[40];
#define p0 k[0]
#define p1 k[1]
#define p2 k[2]
#define p3 k[3]
#define p4 k[4]
#define p5 k[5]
#define saturate(x) clamp(x,0.0,1.0)
in vec2 vUV;in vec2 vUV2;in vec4 vColor;out vec4 outColor;uniform vec4 flip;
uniform sampler2D s0;
vec4 sample_scene(vec2 p){return texture(s0,vec2(p.x,mix(p.y,1.0-p.y,flip[0])));}









const vec3 W = vec3(0.2126, 0.7152, 0.0722);
vec4 shade(vec2 uv )
{
  vec2 dc = uv - 0.5;

  vec2 ab = dc * 2.0 * p1.z * p0.xy;
  vec3 c = vec3(sample_scene( uv + ab).r, sample_scene( uv).g, sample_scene( uv - ab).b);
  c = mix(vec3(dot(c,W)), c, p1.w);
  c = (c - 0.5) * p2.w + 0.5;
  c = c * p3.rgb + p2.rgb * (1.0 - c);
  c = pow(saturate(c), vec3(p3.w));

  float d = length(dc * vec2(p5.x, 1.0)) * p5.y;
  c *= 1.0 - p1.x * smoothstep(p1.y, 1.0, d);
  c = mix(c, p4.rgb, p4.a * smoothstep(0.45, 1.0, d));
  float n = fract(sin(dot(uv + fract(p0.z * 0.37), vec2(12.9898, 78.233))) * 43758.5453);
  c += (n - 0.5) * p0.w;
  return vec4(c, 1.0);
}

void main(){outColor=shade(vUV);}

